inline void Any::type(const object_reference<TypeCode>& tc) {
  if (!h_) h_ = rorb_any_new();
  rustorb::detail::Exc exc;
  rustorb::detail::check(rorb_any_set_type(h_, rustorb::detail::tc_handle(tc), &exc), exc);
}

template <typename W>
void Any::_rorb_insert(const object_reference<TypeCode>& tc, const W& write) {
  struct Ctx {
    const W* write;
    std::exception_ptr error;
  } ctx{&write, nullptr};
  rorb_any* out = nullptr;
  rustorb::detail::Exc exc;
  rorb_status status = rorb_any_insert(
      rustorb::detail::tc_handle(tc),
      [](void* c, rorb_out* o) -> rorb_status {
        auto* x = static_cast<Ctx*>(c);
        try {
          (*x->write)(o);
          return RORB_OK;
        } catch (...) {
          x->error = std::current_exception();
          return RORB_CALLBACK_FAILED;
        }
      },
      &ctx, &out, &exc);
  if (status == RORB_CALLBACK_FAILED && ctx.error) std::rethrow_exception(ctx.error);
  rustorb::detail::check(status, exc);
  rorb_any_release(h_);
  h_ = out;
}

template <typename R>
bool Any::_rorb_extract(const object_reference<TypeCode>& tc, const R& read) const {
  rorb_any* h = _rorb_handle();
  {
    rorb_typecode* mine = rorb_any_type(h);
    bool same = rorb_tc_equivalent(mine, rustorb::detail::tc_handle(tc)) != 0;
    rorb_tc_release(mine);
    if (!same) return false;
  }
  struct Ctx {
    const R* read;
    std::exception_ptr error;
  } ctx{&read, nullptr};
  rustorb::detail::Exc exc;
  rorb_status status = rorb_any_extract(
      h,
      [](void* c, rorb_in* in) -> rorb_status {
        auto* x = static_cast<Ctx*>(c);
        try {
          (*x->read)(in);
          return RORB_OK;
        } catch (...) {
          x->error = std::current_exception();
          return RORB_CALLBACK_FAILED;
        }
      },
      &ctx, &exc);
  if (status == RORB_CALLBACK_FAILED && ctx.error) std::rethrow_exception(ctx.error);
  rustorb::detail::check(status, exc);
  return true;
}

inline ORB::TypeCode_ref ORB::create_struct_tc(const std::string& id, const std::string& name,
                                               const StructMemberSeq& members) {
  std::vector<rustorb::detail::TcMember> m;
  for (const auto& x : members) m.push_back({x.name(), x.type()});
  return rustorb::detail::tc_struct(TCKind::tk_struct, id, name, m);
}

inline ORB::TypeCode_ref ORB::create_exception_tc(const std::string& id,
                                                  const std::string& name,
                                                  const StructMemberSeq& members) {
  std::vector<rustorb::detail::TcMember> m;
  for (const auto& x : members) m.push_back({x.name(), x.type()});
  return rustorb::detail::tc_struct(TCKind::tk_except, id, name, m);
}

inline ORB::TypeCode_ref ORB::create_union_tc(const std::string& id, const std::string& name,
                                              const TypeCode_ref& discriminator_type,
                                              const UnionMemberSeq& members) {
  auto disc = rustorb::detail::typecode(rorb_tc_unaliased(rustorb::detail::tc_handle(discriminator_type)));
  std::vector<rustorb::detail::TcCase> cases;
  int32_t default_index = -1;
  for (const auto& x : members) {
    uint64_t label = 0;
    auto label_type = x.label().type();
    if (label_type->kind() == TCKind::tk_octet && disc->kind() != TCKind::tk_octet) {
      if (default_index >= 0) throw BAD_PARAM(0, CompletionStatus::COMPLETED_NO);
      default_index = static_cast<int32_t>(cases.size());
    } else if (!label_type->equivalent(disc) ||
               !rorb_any_label(x.label()._rorb_handle(), &label)) {
      throw BAD_PARAM(0, CompletionStatus::COMPLETED_NO);
    }
    cases.push_back({label, x.name(), x.type()});
  }
  return rustorb::detail::tc_union(id, name, discriminator_type, cases, default_index);
}

inline ORB::TypeCode_ref ORB::create_enum_tc(const std::string& id, const std::string& name,
                                             const EnumMemberSeq& members) {
  std::vector<std::string_view> m(members.begin(), members.end());
  return rustorb::detail::tc_enum(id, name, m);
}

